/*JSON{
  "type" : "method",
  "class" : "Graphics",
  "name" : "setFontFixedsys16",
  "generate" : "jswrap_graphics_setFontFixedsys16",
  "params" : [
    ["scale","int","[optional] If >1 the font will be scaled up by that amount"]
  ],
  "return" : ["JsVar","The instance of Graphics this was called on, to allow call chaining"],
  "return_object" : "Graphics"
}
Set the current font to FixedSys (1 bpp, cap height = 9 px)
*/
JsVar *jswrap_graphics_setFontFixedsys16(JsVar *parent, int scale) {
  if (scale<1) scale=1;
  JsVar *bitmap = jsvNewNativeString((char *)fontBitmap, sizeof(fontBitmap));
  JsVar *widths = jsvNewNativeString((char *)fontWidths, sizeof(fontWidths));
  JsVar *r = jswrap_graphics_setFontCustom(parent, bitmap, 32, widths, 16 + (scale<<8) + (1<<16)); // 1 bit, total height 16px
  jsvUnLock2(bitmap, widths);
  return r;
}
